type Fetch<T> =
  | { status: 'idle' }
  | { status: 'loading'; startedAt: number }
  | { status: 'success'; data: T }
  | { status: 'failure'; error: string };

function label(f: Fetch<string[]>): string {
  if (f.status === 'success') return `${f.data.length} rows`; // data exists here only
  if (f.status === 'failure') return `error: ${f.error}`;
  return f.status;
}

// const bad: Fetch<string[]> = { status: 'loading', startedAt: 1, error: 'x' };
// error: 'error' does not exist on the loading member

type Res = { ok: true; value: number } | { ok: false; error: string };

function read(r: Res): string {
  const isOk = r.ok;                // aliased condition (TS 4.4)
  if (isOk) return String(r.value);
  return r.error;
}

type Action = { kind: 'add'; payload: number } | { kind: 'rename'; payload: string };

function apply(action: Action): string {
  const { kind, payload } = action; // destructured siblings (TS 4.6)
  return kind === 'add' ? payload.toFixed(0) : payload.toUpperCase();
}

function pad(input: string | number | Date | null): string {
  if (input == null) return '-';            // null and undefined
  if (input instanceof Date) return input.toISOString();
  if (typeof input === 'number') return input.toFixed(2);
  return input.trim();                      // only string remains
}

