type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'square'; side: number }
  | { kind: 'tri'; base: number; h: number };

function assertNever(x: never): never {
  throw new Error(`Unhandled: ${JSON.stringify(x)}`);
}

function area(s: Shape): number {
  switch (s.kind) {
    case 'circle': return Math.PI * s.r * s.r;
    case 'square': return s.side * s.side;
    case 'tri':    return (s.base * s.h) / 2;
    default:       return assertNever(s);  // s: never here
  }
}

interface User { name: string; age: number }

function isUserLoose(x: unknown): x is User {
  return typeof x === 'object' && x !== null && 'name' in x;   // compiles, lies
}

function isUser(x: unknown): x is User {
  if (typeof x !== 'object' || x === null || !('name' in x) || !('age' in x)) return false;
  return typeof x.name === 'string' && typeof x.age === 'number';
}

function assertUser(x: unknown): asserts x is User {
  if (!isUser(x)) throw new TypeError('not a User');
}

