type RequestState =
  | { status: 'idle' }
  | { status: 'loading'; attempt: number }
  | { status: 'success'; data: string[] }
  | { status: 'failure'; error: string; attempt: number };

function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}

function render(state: RequestState): string {
  switch (state.status) {
    case 'idle':    return 'Press load';
    case 'loading': return `Loading (try ${state.attempt})...`;
    case 'success': return state.data.length ? state.data.join(', ') : 'No results';
    case 'failure': return `Failed after ${state.attempt}: ${state.error}`;
    default:        return assertNever(state);
  }
}

console.log(render({ status: 'loading', attempt: 2 }));      // Loading (try 2)...
console.log(render({ status: 'success', data: ['a', 'b'] })); // a, b

