solution:
type RequestState =
  | { status: 'idle' }
  | { status: 'loading'; attempt: number }
  | { status: 'success'; data: string[] }
  | { status: 'failure'; error: string; attempt: number };

type RequestEvent =
  | { type: 'FETCH' }
  | { type: 'RESOLVE'; data: string[] }
  | { type: 'REJECT'; error: string }
  | { type: 'RETRY' }
  | { type: 'RESET' };

const MAX_ATTEMPTS = 3;

function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}

function transition(state: RequestState, event: RequestEvent): RequestState {
  switch (event.type) {
    case 'FETCH':
      return state.status === 'loading' ? state : { status: 'loading', attempt: 1 };
    case 'RESOLVE':
      return state.status === 'loading' ? { status: 'success', data: event.data } : state;
    case 'REJECT':
      return state.status === 'loading'
        ? { status: 'failure', error: event.error, attempt: state.attempt }
        : state;
    case 'RETRY':
      return state.status === 'failure' && state.attempt < MAX_ATTEMPTS
        ? { status: 'loading', attempt: state.attempt + 1 }
        : state;
    case 'RESET':
      return { status: 'idle' };
    default:
      return assertNever(event);
  }
}

Both types are discriminated unions, so every state literal is checked against exactly one member: `{ status: 'idle', data: [] }` or a `failure` without an error is a compile error, and the typeChecks prove it. Switching on `event.type` narrows the event, so `event.data` exists only in the `RESOLVE` case; comparing `state.status` narrows the state, so `state.attempt` is read only where it exists. Stale events (a `RESOLVE` after `RESET`) return the same state object, which also lets a UI skip re-rendering. The `default` branch receives `never`; if someone adds a `CANCEL` event to the union, `assertNever(event)` stops compiling until a case is written, and at runtime an unexpected event object throws instead of silently doing nothing. Each call is O(1) and creates at most one small object.

