type Line =
  | { kind: 'item'; sku: string; price: number; qty: number }
  | { kind: 'discount'; percent: number }
  | { kind: 'shipping'; cost: number };

interface Order { lines: Line[] }

type CheckoutResult = { ok: true; total: number } | { ok: false; error: string };

function assertNever(value: never): never {
  throw new Error(`Unhandled line: ${JSON.stringify(value)}`);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAmount(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}

function assertLine(value: unknown, at: string): asserts value is Line {
  if (!isRecord(value)) throw new TypeError(`${at}: expected an object`);
  switch (value.kind) {
    case 'item': {
      const { sku, price, qty } = value;
      const ok = typeof sku === 'string' && sku !== '' && isAmount(price) &&
        typeof qty === 'number' && Number.isInteger(qty) && qty >= 1;
      if (!ok) throw new TypeError(`${at}: invalid item`);
      return;
    }
    case 'discount': {
      const { percent } = value;
      if (!isAmount(percent) || percent > 100) throw new TypeError(`${at}: invalid discount`);
      return;
    }
    case 'shipping':
      if (!isAmount(value.cost)) throw new TypeError(`${at}: invalid shipping`);
      return;
    default:
      throw new TypeError(`${at}: unknown kind`);
  }
}

function assertOrder(value: unknown): asserts value is Order {
  const lines = isRecord(value) ? value.lines : undefined;
  if (!Array.isArray(lines)) throw new TypeError('expected { lines: [...] }');
  lines.forEach((line: unknown, i: number) => assertLine(line, `lines[${i}]`));
}

function checkout(input: unknown): CheckoutResult {
  try {
    assertOrder(input);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
  let subtotal = 0;
  let percent = 0;
  let shipping = 0;
  for (const line of input.lines) {
    switch (line.kind) {
      case 'item':
        subtotal += line.price * line.qty;
        break;
      case 'discount':
        percent += line.percent;
        break;
      case 'shipping':
        shipping += line.cost;
        break;
      default:
        assertNever(line);
    }
  }
  const total = subtotal * (1 - Math.min(percent, 100) / 100) + shipping;
  return { ok: true, total: Math.round(total * 100) / 100 };
}

